package com.vinnyvangogh.questpath;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Every quest, with what it needs and what it grants.
 *
 * <p>Bundled as a jar resource and generated by questpath's
 * {@code -export-quest-graph}. Nobody transcribes 218 quests by hand, and the
 * bundle is what lets the panel answer without questpath running — which is
 * the difference between a plugin and a remote control.
 *
 * <p>It goes stale: the graph updates when this plugin is released, not when
 * the wiki changes. That is a real cost and the reason questpath stays the
 * place where a correction lands first.
 */
class QuestGraph
{
	/**
	 * The graph shape this build understands.
	 *
	 * A version it does not know is refused rather than parsed. A graph
	 * missing a field parses cleanly into nulls and then answers "eligible"
	 * for a quest whose requirements were never read — a confident wrong
	 * answer, which is the one thing this plugin must not produce.
	 *
	 * 2 added Item.sources(). 3 added Item.itemId(), which is what the
	 * overlays draw the game's own sprite from -- searching the item cache by
	 * name instead would re-derive a disambiguation questpath's 16,472-row
	 * catalogue has already done, and get it wrong: "Bucket" matches a
	 * Meiyerditch bucket and an animation-only bucket as readily as the real
	 * one. 4 added Item.unresolved(), the wiki lines the catalogue could not
	 * place -- 354 of 1,301 -- which used to be dropped from the bundle
	 * without trace, leaving every quest's item list quietly short while
	 * presenting itself as the list.
	 */
	static final int SUPPORTED_VERSION = 6;

	@SerializedName("version")
	private int version;

	@SerializedName("quests")
	private List<Quest> quests;

	@SerializedName("boosts")
	private List<Boost> boosts;

	/**
	 * One temporary skill boost, with the size the requirement flag never
	 * had.
	 *
	 * A requirement's {@code boostable} is a bare yes from the wiki: it says
	 * a boost is allowed and never how large one can be. Without these, a
	 * fifty-level shortfall and a one-level shortfall are indistinguishable,
	 * which is the bug they exist to close.
	 */
	static class Boost
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("item")
		private String item;

		@SerializedName("base")
		private int base;

		@SerializedName("per_level")
		private double perLevel;

		@SerializedName("max")
		private int max;

		@SerializedName("random")
		private boolean random;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		String item()
		{
			return item == null ? "" : item;
		}

		/** The increase at level 0, or the whole increase when flat. */
		int base()
		{
			return base;
		}

		/** The fraction of the account's level added on top; zero when flat. */
		double perLevel()
		{
			return perLevel;
		}

		/** The wiki's stated ceiling, or zero when it states one number. */
		int max()
		{
			return max;
		}

		/** Whether this one can drain instead of boosting -- the stews. */
		boolean random()
		{
			return random;
		}
	}

	/** One quest as the verdict engine sees it. */
	static class Quest
	{
		@SerializedName("id")
		private long id;

		@SerializedName("slug")
		private String slug;

		@SerializedName("name")
		private String name;

		@SerializedName("members")
		private boolean members;

		@SerializedName("prerequisites")
		private List<Long> prerequisites;

		@SerializedName("prerequisites_started_only")
		private List<Long> prerequisitesStartedOnly;

		@SerializedName("requirements")
		private List<Requirement> requirements;

		@SerializedName("rewards")
		private List<Reward> rewards;

		@SerializedName("items")
		private List<Item> items;

		long id()
		{
			return id;
		}

		String slug()
		{
			return slug == null ? "" : slug;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		boolean members()
		{
			return members;
		}

		List<Long> prerequisites()
		{
			return prerequisites == null ? Collections.emptyList() : prerequisites;
		}

		/**
		 * The subset of {@link #prerequisites()} satisfied by having *started*
		 * the quest rather than finished it -- the wiki's "Started [[X]]"
		 * phrasing. Both planners must apply this identically or their
		 * verdicts diverge, which is what PlannerVectorsTest exists to catch.
		 */
		boolean requiresStartedOnly(long prerequisiteId)
		{
			if (prerequisitesStartedOnly == null)
			{
				return false;
			}
			return prerequisitesStartedOnly.contains(prerequisiteId);
		}

		List<Requirement> requirements()
		{
			return requirements == null ? Collections.emptyList() : requirements;
		}

		List<Reward> rewards()
		{
			return rewards == null ? Collections.emptyList() : rewards;
		}

		List<Item> items()
		{
			return items == null ? Collections.emptyList() : items;
		}
	}

	/** One thing a quest needs, already resolved to a catalogue item name. */
	static class Item
	{
		@SerializedName("name")
		private String name;

		@SerializedName("item_id")
		private int itemId;

		@SerializedName("quantity")
		private int quantity;

		@SerializedName("unresolved")
		private boolean unresolved;

		@SerializedName("optional")
		private boolean optional;

		@SerializedName("obtainable")
		private boolean obtainable;

		@SerializedName("sources")
		private List<String> sources;

		String name()
		{
			return name == null ? "" : name;
		}

		/**
		 * The count the wiki stated, or 0 when it stated none.
		 *
		 * Zero is not one. Plenty of lines name a thing without saying how
		 * many, and defaulting to one would invent a number the wiki did not
		 * give.
		 */
		int quantity()
		{
			return quantity;
		}

		/**
		 * The game's own item id, or 0 when questpath holds none.
		 *
		 * Zero means "no id", not item 0: questpath omits the field rather
		 * than sending a zero precisely so this stays unambiguous, because
		 * item 0 is a real item and would render as confident, wrong art for
		 * something the catalogue could not actually identify. Callers must
		 * treat 0 as "draw no icon".
		 */
		int itemId()
		{
			return itemId;
		}

		/**
		 * Whether this is a wiki line questpath could not match to a real
		 * item.
		 *
		 * name() then carries the wiki's own words rather than an item name,
		 * there is no id, and nothing can tick it against a bank. It is shown
		 * anyway: dropping it would make the rest of the list a lie, because
		 * the panel would present four items as everything the quest needs
		 * when the wiki listed five.
		 */
		boolean unresolved()
		{
			return unresolved;
		}

		boolean optional()
		{
			return optional;
		}

		/** Whether the wiki says this can be picked up during the quest itself. */
		boolean obtainable()
		{
			return obtainable;
		}

		/**
		 * Where to get this item, best first, as short display lines ready to
		 * show verbatim -- "Shop: Varrock General Store (5 gp)", "Drop: Goblin
		 * (common)". Empty when questpath found no source at all, which the
		 * panel must render as no tooltip, never an empty or invented one.
		 */
		List<String> sources()
		{
			return sources == null ? Collections.emptyList() : sources;
		}
	}

	/** A skill level a quest demands. */
	static class Requirement
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("level")
		private int level;

		@SerializedName("boostable")
		private boolean boostable;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		int level()
		{
			return level;
		}

		/**
		 * Boostable rescues a skill gap but never a cap violation: a boost is
		 * relative to the base level, so an Attack capped at 1 cannot reach a
		 * boostable requirement of 15.
		 */
		boolean boostable()
		{
			return boostable;
		}
	}

	/** Unavoidable experience a quest grants. */
	static class Reward
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("xp")
		private double xp;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		double xp()
		{
			return xp;
		}
	}

	private Map<Long, Quest> byId;

	int version()
	{
		return version;
	}

	List<Quest> quests()
	{
		return quests == null ? Collections.emptyList() : quests;
	}

	/** Every temporary skill boost the bundle carries. */
	List<Boost> boosts()
	{
		return boosts == null ? Collections.emptyList() : boosts;
	}

	/** One quest by id, or null when the graph does not carry it. */
	Quest get(long id)
	{
		if (byId == null)
		{
			Map<Long, Quest> index = new LinkedHashMap<>();
			for (Quest quest : quests())
			{
				index.put(quest.id(), quest);
			}
			byId = index;
		}
		return byId.get(id);
	}

	/**
	 * Loads the bundled graph.
	 *
	 * <p>{@code getResourceAsStream}, never {@code getResource}: resources
	 * ship inside a jar, and a URL to one is not a file path.
	 *
	 * @throws IOException when the resource is missing, unreadable, or carries
	 *     a version this build does not understand
	 */
	static QuestGraph load(Gson gson) throws IOException
	{
		try (InputStream stream = QuestGraph.class.getResourceAsStream("quests.json"))
		{
			if (stream == null)
			{
				throw new IOException("bundled quests.json is missing from the jar");
			}
			QuestGraph graph = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), QuestGraph.class);
			if (graph == null)
			{
				throw new IOException("bundled quests.json did not parse");
			}
			if (graph.version() != SUPPORTED_VERSION)
			{
				throw new IOException("bundled quests.json is version " + graph.version()
					+ ", this build understands " + SUPPORTED_VERSION);
			}
			if (graph.quests().isEmpty())
			{
				// An empty graph makes every quest unknown, which renders as
				// "not found" rather than as "the bundle is broken".
				throw new IOException("bundled quests.json carries no quests");
			}
			return graph;
		}
	}
}
